using Dapper;
using Microsoft.Extensions.Configuration;
using MySqlConnector;
using ReadBookRepo.Publishing;
namespace ReadBookRepo.Media;
public sealed class MediaRepository(IConfiguration configuration):IMediaRepository
{
    private readonly string _cs=configuration.GetConnectionString("Default")??throw new InvalidOperationException("ConnectionStrings:Default is not configured.");
    public async Task EnsureActiveUserAsync(Guid userId,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);var ok=await c.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM `user` WHERE user_id=@UserId AND status=1)",new{UserId=userId},cancellationToken:ct));if(!ok)throw new PublishingException(403,"Tài khoản không hoạt động.");}
    public async Task UpdateAvatarAsync(Guid userId,string url,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);var n=await c.ExecuteAsync(new CommandDefinition("UPDATE `user` SET avatar_url=@Url WHERE user_id=@UserId AND status=1",new{Url=url,UserId=userId},cancellationToken:ct));if(n!=1)throw new PublishingException(403,"Tài khoản không hoạt động.");}
    public async Task EnsureOwnedNovelAsync(Guid userId,Guid novelId,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);var ok=await c.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM `novel` n JOIN `user` u ON u.user_id=n.uploader_id WHERE n.novel_id=@NovelId AND n.uploader_id=@UserId AND n.deleted_at IS NULL AND u.status=1 AND u.role=1)",new{UserId=userId,NovelId=novelId},cancellationToken:ct));if(!ok)throw new PublishingException(404,"Không tìm thấy truyện hoặc bạn không có quyền.");}
    public async Task<CoverUpdateResult> SetCoverAsync(Guid userId,Guid novelId,string url,CancellationToken ct=default)
    {await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var n=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("SELECT n.* FROM `novel` n JOIN `user` u ON u.user_id=n.uploader_id WHERE n.novel_id=@NovelId AND n.uploader_id=@UserId AND n.deleted_at IS NULL AND u.status=1 AND u.role=1 FOR UPDATE",new{UserId=userId,NovelId=novelId},tx,cancellationToken:ct));if(n is null)throw new PublishingException(404,"Không tìm thấy truyện hoặc bạn không có quyền.");if((sbyte)n.review_status==1){var pending=await c.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM novel_revision WHERE novel_id=@NovelId AND review_status=0)",new{NovelId=novelId},tx,cancellationToken:ct));if(pending)throw new PublishingException(409,"Truyện đã có bản sửa đang chờ duyệt.");var id=Guid.NewGuid();await c.ExecuteAsync(new CommandDefinition("INSERT INTO novel_revision(revision_id,novel_id,submitted_by,title,original_author,source_type,source_url,description,cover_url,completion_status) VALUES(@Id,@NovelId,@UserId,@Title,@OriginalAuthor,@SourceType,@SourceUrl,@Description,@Url,@CompletionStatus)",new{Id=id,NovelId=novelId,UserId=userId,Title=(string)n.title,OriginalAuthor=(string?)n.original_author,SourceType=(sbyte)n.source_type,SourceUrl=(string?)n.source_url,Description=(string?)n.description,Url=url,CompletionStatus=(sbyte)n.completion_status},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(id,true);}await c.ExecuteAsync(new CommandDefinition("UPDATE `novel` SET cover_url=@Url,review_status=0,reject_reason=NULL WHERE novel_id=@NovelId",new{Url=url,NovelId=novelId},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(null,false);}
    public async Task<HashSet<string>> GetReferencedMediaUrlsAsync(CancellationToken ct=default){await using var c=new MySqlConnection(_cs);var urls=await c.QueryAsync<string>(new CommandDefinition("SELECT avatar_url FROM `user` WHERE avatar_url IS NOT NULL AND avatar_url<>'' UNION SELECT cover_url FROM novel WHERE cover_url IS NOT NULL AND cover_url<>'' UNION SELECT cover_url FROM novel_revision WHERE cover_url IS NOT NULL AND cover_url<>''",cancellationToken:ct));return urls.ToHashSet(StringComparer.Ordinal);}
}
